String query = "SELECT * FROM users WHERE name = " + name + " AND email = " + email; SQLDataSource sqlDataSource = new SQLDataSource(); sqlDataSource.setDataSource("jdbc:mysql://localhost:3306/mydb"); statement = sqlDataSource.getConnection().prepareStatement(query); statement.setXXX(name); statement.setXXX(email); statement.execute(); SQLDataSource.close();
 String query = "SELECT * FROM users WHERE name = ? AND email = ?"; SQLDataSource sqlDataSource = new SQLDataSource(); sqlDataSource.setDataSource("jdbc:mysql://localhost:3306/mydb"); PreparedStatement statement = sqlDataSource.getConnection().prepareStatement(query); statement.setObject(1, name); statement.setObject(2, email); statement.execute(); SQLDataSource.close();
